7	export const SIDEBAR_SCROLL_STORAGE_KEY = 'flowguard_sidebar_scroll';
8	
9	const Sidebar = () => {
10	  const navigate = useNavigate();
11	  const navRef = useRef(null);
12	  const [user] = useState(() => {
13	    const storedName = localStorage.getItem("userName");
14	    const storedRole = localStorage.getItem("userRole");
15	    return storedName && storedRole
16	      ? { name: storedName, role: storedRole }
17	      : { name: 'Guest', role: ROLES.TENANT };
18	  });
19	  const [isOpen, setIsOpen] = useState(false);
20	
21	  useLayoutEffect(() => {
22	    const nav = navRef.current;
23	    if (!nav) return undefined;
24	
25	    const restoreScroll = () => {
26	      const stored = Number(sessionStorage.getItem(SIDEBAR_SCROLL_STORAGE_KEY) || 0);
27	      if (Number.isFinite(stored) && stored > 0) {
28	        nav.scrollTop = stored;
29	      }
30	    };
31	
32	    // Restore BEFORE the browser paints so the active item never flashes at
33	    // the top; the rAF reapply is only a fallback for late layout/CSS shifts.
34	    restoreScroll();
35	    const frame = requestAnimationFrame(restoreScroll);
36	
37	    const saveScroll = () => {
38	      sessionStorage.setItem(SIDEBAR_SCROLL_STORAGE_KEY, String(nav.scrollTop));
39	    };
40	    nav.addEventListener('scroll', saveScroll, { passive: true });
41	
42	    return () => {
43	      cancelAnimationFrame(frame);
44	      nav.removeEventListener('scroll', saveScroll);
45	      saveScroll();
46	    };
47	  }, []);
48	
49	  // Visibility helpers — keep these in lock-step with the route wrappers in App.jsx
50	  // so a user never sees a link that would only bounce them to the 403 page.
